import { readFileSync, writeFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { spawnSync, execFileSync } from 'node:child_process';
const path = 'src/server/maintenance/supervisor-test-control.ts';
const original = readFileSync(path, 'utf8');
const needle = 'if (!observed) finish({ error });';
if (original.split(needle).length !== 2) throw new Error('Expected one failure propagation site');
const changed = original.replace(needle, 'void error; // Counterfactual: discard the pre-barrier rejection.');
const sha = (s: string) => createHash('sha256').update(s).digest('hex');
let result: ReturnType<typeof spawnSync> | undefined;
const source = execFileSync('git', ['rev-parse', 'HEAD'], { encoding: 'utf8' }).trim();
try {
  writeFileSync(path, changed);
  result = spawnSync(process.execPath, ['node_modules/.bin/vitest', 'run', 'src/server/maintenance/supervisor-test-control.test.ts', '-t', 'pre-barrier', '--cache=false', '--fsModuleCachePath', '/tmp/spn160-vitest-negative'], { stdio: 'inherit' });
} finally {
  writeFileSync(path, original);
  const restored = readFileSync(path, 'utf8');
  const receipt = { source, contract: 'Pre-barrier rejection must retain its contextual cause immediately before the original deadline', path, originalSha256: sha(original), mutatedSha256: sha(changed), restoredSha256: sha(restored), command: 'vitest run supervisor-test-control.test.ts -t pre-barrier with private cache', status: result?.status, signal: result?.signal, restored: restored === original };
  writeFileSync('/tmp/spinel-dependabot-2026-11-11/spn160-negative-source.json', JSON.stringify(receipt, null, 2) + '\n');
  if (restored !== original) throw new Error('Source restoration mismatch');
}
process.exitCode = result?.status ?? 1;
